struct Circle {
    radius: f64,
}

#[derive(Debug)]
struct Rect {
    width: f64,
    height: f64,
}

trait Shape {
    fn area(&self) -> f64;
}

impl Shape for Circle {
    fn area(&self) -> f64 {
        std::f64::consts::PI * self.radius * self.radius
    }
}

impl Shape for Rect {
    fn area(&self) -> f64 {
        self.width * self.height
    }
}

// one bound: any type that implements Shape
fn total_area<T: Shape>(shapes: &[T]) -> f64 {
    let mut sum = 0.0;
    for shape in shapes {
        sum += shape.area();
    }
    sum
}

// two bounds, spelled out with where
fn report<T>(shape: &T) -> String
where
    T: Shape + std::fmt::Debug,
{
    format!("{:?} has area {:.2}", shape, shape.area())
}

fn main() {
    let circles = vec![Circle { radius: 1.0 }, Circle { radius: 2.0 }];
    let r = Rect { width: 2.0, height: 3.0 };

    println!("total {:.2}", total_area(&circles));
    println!("{}", report(&r));
}

#[derive(Debug, Clone, PartialEq)]
struct Point {
    x: i32,
    y: i32,
}

fn main() {
    let a = Point { x: 1, y: 2 };
    let b = a.clone();
    let c = Point { x: 9, y: 2 };

    println!("a == b: {}", a == b);
    println!("a == c: {}", a == c);
    println!("b is {:?}", b);
}

