// argument position: anything that implements Shape
fn show(shape: impl Shape) {
    println!("{} {:.2}", shape.name(), shape.area());
}

// return position: one concrete type, name withheld
fn unit_circle() -> impl Shape {
    Circle { radius: 1.0 }
}

fn main() {
    show(unit_circle());
    show(Rect { width: 2.0, height: 3.0 });
}

struct Circle {
    radius: f64,
}

struct Rect {
    width: f64,
    height: f64,
}

trait Shape {
    fn area(&self) -> f64;
    fn name(&self) -> &'static str;
}

impl Shape for Circle {
    fn area(&self) -> f64 {
        std::f64::consts::PI * self.radius * self.radius
    }

    fn name(&self) -> &'static str {
        "circle"
    }
}

impl Shape for Rect {
    fn area(&self) -> f64 {
        self.width * self.height
    }

    fn name(&self) -> &'static str {
        "rect"
    }
}

fn main() {
    let shapes: Vec<Box<dyn Shape>> = vec![
        Box::new(Circle { radius: 2.0 }),
        Box::new(Rect { width: 3.0, height: 4.0 }),
    ];

    let mut total = 0.0;
    for shape in &shapes {
        println!("{} {:.2}", shape.name(), shape.area());
        total += shape.area();
    }
    println!("total {:.2}", total);
}

