exercise.solution:
struct Triangle {
    base: f64,
    height: f64,
}

trait Area {
    fn area(&self) -> f64;
}

impl Area for Triangle {
    fn area(&self) -> f64 {
        self.base * self.height / 2.0
    }
}

fn main() {
    let t = Triangle { base: 4.0, height: 3.0 };
    println!("area = {:.2}", t.area());
}
